package com.gamehub.application.service; import com.gamehub.application.OperationsService; import java.util.List; public final class PaymentService { private final OperationsService ops; public PaymentService(OperationsService ops){this.ops=ops;} public List<String> outstanding()throws Exception{return ops.outstandingCharges();} public long settle(long a,long c,long amount,String method,String ref)throws Exception{if(amount<=0||ref==null||ref.isBlank())throw new IllegalArgumentException("Amount and reference are required");return ops.payChargeAsStaff(a,c,amount,method,ref);} }